
(async () => {
  const csrfToken = document.cookie.match(/csrftoken=([^;]+)/)[1];
  const B64_DATA = {"6": "", "8": ""};
  const results = [];
  for (const [ch, b64] of Object.entries(B64_DATA)) {
    try {
      const binary = atob(b64);
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      const blob = new Blob([bytes], {type: 'application/zip'});
      const fd = new FormData();
      fd.append('file', blob, 'chapter'+ch+'.zip');
      const resp = await fetch('/api/admin/import_problem/', {
        method: 'POST', headers: {'X-CSRFToken': csrfToken}, body: fd
      });
      const d = await resp.json();
      results.push({ch, count: d.data?.import_count, error: d.error});
    } catch(e) {
      results.push({ch, error: e.message});
    }
  }
  return results;
})()
